package com.example.home_api.web;

import jakarta.servlet.http.HttpSession;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Controller
public class FinanceController {
    private final FinanceService service;
    private final JdbcTemplate jdbc;
    public FinanceController(FinanceService service,JdbcTemplate jdbc){this.service=service;this.jdbc=jdbc;}
    @GetMapping("/") String dashboard(@RequestParam(required=false) Integer year,@RequestParam(required=false) Integer month,Authentication auth,HttpSession session,Model model){
        if(session.getAttribute("activeGroupId")==null){model.addAttribute("applications",jdbc.queryForList("SELECT gm.group_id,g.group_name,gm.approve_flag,gm.create_date FROM group_member gm JOIN \"group\" g ON g.group_id=gm.group_id WHERE gm.user_id=? AND gm.approve_flag=0 AND gm.removed_at IS NULL ORDER BY gm.create_date DESC",auth.getName()));model.addAttribute("groups",jdbc.queryForList("SELECT g.group_id,g.group_name,gm.leader_flag,gm.create_date FROM group_member gm JOIN \"group\" g ON g.group_id=gm.group_id WHERE gm.user_id=? AND gm.approve_flag=1 AND g.status='ACTIVE' ORDER BY g.group_name",auth.getName()));return "user-dashboard";}
        YearMonth ym=normalize(year,month);String group=activeGroup(session);common(model,ym,group,session);model.addAttribute("pendingMembers",jdbc.queryForList("SELECT u.user_id,u.user_name,gm.create_date FROM group_member gm JOIN \"user\" u ON u.user_id=gm.user_id WHERE gm.group_id=? AND gm.approve_flag=0 AND gm.removed_at IS NULL ORDER BY gm.create_date",group));model.addAttribute("isLeader",Boolean.TRUE.equals(session.getAttribute("activeGroupLeader")));
        model.addAttribute("summary",service.summary(group,ym.getYear(),ym.getMonthValue()));model.addAttribute("categorySummary",service.categorySummary(group,ym.getYear(),ym.getMonthValue()));
        model.addAttribute("recent",service.shopping(group,ym.getYear(),ym.getMonthValue()).stream().limit(10).toList());return "dashboard";}
    @GetMapping("/budgets") String budgets(@RequestParam(required=false) Integer year,@RequestParam(required=false) Integer month,HttpSession session,Model model){YearMonth ym=normalize(year,month);String group=activeGroup(session);common(model,ym,group,session);model.addAttribute("rows",service.budgets(group,ym.getYear(),ym.getMonthValue()));model.addAttribute("total",service.budgetTotal(group,ym.getYear(),ym.getMonthValue()));model.addAttribute("invalidBudgetCount",jdbc.queryForObject("SELECT count(*) FROM budgets b LEFT JOIN category c ON c.id=b.category_id AND c.group_id=b.group_id WHERE b.group_id=? AND b.year=? AND b.month=? AND (c.id IS NULL OR c.disabled_flag<>0)",Integer.class,group,ym.getYear(),ym.getMonthValue()));return "budgets";}
    @PostMapping("/budgets") String budget(@RequestParam int year,@RequestParam int month,@RequestParam List<String> categoryIds,@RequestParam List<Integer> amounts,@RequestParam(required=false,defaultValue="false") boolean applyAllMonths,HttpSession session){validatePeriod(year,month);String group=activeGroup(session);if(service.monthFixed(group,year,month)||(applyAllMonths&&service.yearHasFixedMonth(group,year)))return "redirect:/budgets?year="+year+"&month="+month+"&error=closed";service.saveBudgets(group,year,month,categoryIds,amounts,applyAllMonths);return "redirect:/budgets?year="+year+"&month="+month+"&saved";}
    @PostMapping("/budgets/copy-previous") String copyPrevious(@RequestParam int year,@RequestParam int month,HttpSession session){validatePeriod(year,month);String group=activeGroup(session);if(service.monthFixed(group,year,month))return "redirect:/budgets?year="+year+"&month="+month+"&error=closed";service.copyPreviousBudgets(group,YearMonth.of(year,month));return "redirect:/budgets?year="+year+"&month="+month+"&copied";}
    @GetMapping("/budgets/yearly") String budgetYearly(@RequestParam(required=false) Integer year,HttpSession session,Model model){int target=year==null?YearMonth.now().getYear():year;if(target<2000||target>2100)target=YearMonth.now().getYear();String group=activeGroup(session);var totals=service.yearlyBudgetMonthTotals(group,target);model.addAttribute("year",target);model.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));model.addAttribute("rows",service.yearlyBudgets(group,target));model.addAttribute("monthTotals",totals);model.addAttribute("yearTotal",totals.stream().mapToLong(Long::longValue).sum());return "budget-yearly";}
    @GetMapping("/communication") String communication(@RequestParam(required=false) String keyword,@RequestParam(required=false) Integer returnFlag,HttpSession session,Model model){String group=activeGroup(session);model.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));model.addAttribute("keyword",keyword);model.addAttribute("returnFlag",returnFlag);model.addAttribute("rows",service.communications(group,keyword,returnFlag));return "communication";}
    @GetMapping("/communication/new") String communicationNew(HttpSession session,Model model){model.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));model.addAttribute("form",new FinanceService.CommunicationForm(LocalDate.now(),"","","",0,""));return "communication-form";}
    @PostMapping("/communication") String communication(@ModelAttribute FinanceService.CommunicationForm form,HttpSession session,Model model){try{service.addCommunication(activeGroup(session),form);return "redirect:/communication?saved";}catch(Exception e){model.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));model.addAttribute("error","入力内容が不正です。");model.addAttribute("form",form);return "communication-form";}}
    @GetMapping("/communication/{id}") String communicationEdit(@PathVariable int id,HttpSession session,Model model){model.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));model.addAttribute("row",service.communication(activeGroup(session),id));return "communication-edit";}
    @PostMapping("/communication/{id}") String communicationUpdate(@PathVariable int id,@ModelAttribute FinanceService.CommunicationEditForm form,HttpSession session,Model model){try{var normalized=new FinanceService.CommunicationEditForm(id,form.receiveDate(),form.receiveFrom(),form.receiveTo(),form.receiveItem(),form.receiveAmount(),form.receiveRemarks(),form.returnDate(),form.returnItem(),form.returnAmount(),form.returnRemarks(),form.returnFlag());service.updateCommunication(activeGroup(session),normalized);return "redirect:/communication/"+id+"?updated";}catch(Exception e){model.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));model.addAttribute("error","入力内容を確認してください。");model.addAttribute("row",service.communication(activeGroup(session),id));return "communication-edit";}}
    private void common(Model m,YearMonth ym,String group,HttpSession session){m.addAttribute("year",ym.getYear());m.addAttribute("month",ym.getMonthValue());m.addAttribute("categories",service.categories(group));m.addAttribute("activeGroupName",session.getAttribute("activeGroupName"));}
    private String activeGroup(HttpSession session){Object id=session.getAttribute("activeGroupId");if(id==null)throw new IllegalStateException("所属グループが選択されていません");return id.toString();}
    private YearMonth normalize(Integer y,Integer m){return y==null||m==null||m<1||m>12?YearMonth.now():YearMonth.of(y,m);}
    private void validatePeriod(int year,int month){if(year<2000||year>2100||month<1||month>12)throw new IllegalArgumentException("対象年月が不正です");}
}
